∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace Real E] {H : Type u_2}
  [inst_2 : TopologicalSpace H] {I : ModelWithCorners Real E H} {M : Type u_3} [inst_3 : MetricSpace M]
  [inst_4 : ChartedSpace H M] [inst_5 : IsManifold I (WithTop.some instTopENat.top) M] [inst_6 : CompactSpace M]
  [inst_7 : GromovCompactness.ClosedTameTarget I M] {u_seq : Nat → GromovCompactness.CP1.Elem → M} {B : Real}
  {th : GromovCompactness.Bubbling.TargetThresholds I M}
  {cdata : GromovCompactness.Compactness.ConcentrationData I u_seq B th} {m_defect : GromovCompactness.CP1.Elem → Real}
  {s : Finset GromovCompactness.CP1.Elem}
  (self : GromovCompactness.Assembly.PartialRootGraftedTree I u_seq B th cdata m_defect s) (v w : self.tree.V)
  (h : self.tree.adj.Adj v w), Eq (self.map v (self.tree.node_point v w h)) (self.map w (self.tree.node_point w v ⋯))

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace Real E] {H : Type u_2}
  [inst_2 : TopologicalSpace H] {I : ModelWithCorners Real E H} {M : Type u_3} [inst_3 : MetricSpace M]
  [inst_4 : ChartedSpace H M] [inst_5 : IsManifold I (WithTop.some instTopENat.top) M] [inst_6 : CompactSpace M]
  [inst_7 : GromovCompactness.ClosedTameTarget I M] {k : Nat}
  (self : GromovCompactness.Extensions.MarkedStableTreeLimit I k) (i : Fin k) (w : self.tree.V)
  (h : self.tree.adj.Adj (self.mark_vertex i) w), Ne (self.mark_point i) (self.tree.node_point (self.mark_vertex i) w h)

∀ {E : Type u_1} {inst : NormedAddCommGroup E} {inst_1 : NormedSpace Real E} {H : Type u_2}
  {inst_2 : TopologicalSpace H} {I : ModelWithCorners Real E H} {M : Type u_3} {inst_3 : MetricSpace M}
  {inst_4 : ChartedSpace H M} {inst_5 : IsManifold I (WithTop.some instTopENat.top) M} {inst_6 : CompactSpace M}
  {inst_7 : GromovCompactness.ClosedTameTarget I M} {u_seq : Nat → GromovCompactness.CP1.Elem → M} {B : Real}
  {thresh : GromovCompactness.Analysis.TargetThresholds I M} {σ : GromovCompactness.Bookkeeping.SubseqMap}
  {μ : MeasureTheory.Measure GromovCompactness.CP1.Elem} {μ_fin : MeasureTheory.IsFiniteMeasure μ}
  {μ_total_le : ENNReal.instLE.le (MeasureTheory.Measure.instFunLike.coe μ Set.univ) (ENNReal.ofReal B)}
  {weak_lim :
    GromovCompactness.Compactness.WeakMeasureConvergence
      (fun n => GromovCompactness.energyMeasureExtended I (u_seq (σ.val n))) μ}
  {S : Finset GromovCompactness.CP1.Elem}
  {S_def :
    ∀ (p : GromovCompactness.CP1.Elem),
      Iff (SetLike.instMembership.mem S p)
        (ENNReal.instLE.le (ENNReal.ofReal thresh.ε_reg)
          (MeasureTheory.Measure.instFunLike.coe μ (Set.instSingletonSet.singleton p)))}
  {card_S_mul_le : Real.instLE.le (instHMul.hMul S.card.cast thresh.ε_reg) B}
  {card_S_le : Real.instLE.le S.card.cast (instHDiv.hDiv B thresh.ε_reg)} {u₀ : GromovCompactness.CP1.Elem → M}
  {u₀_jhol : GromovCompactness.JHolomorphicOn I GromovCompactness.I_CP1 u₀ Set.univ}
  {smooth_conv :
    GromovCompactness.SmoothLocalConvergesOn I (fun n => u_seq (σ.val n)) u₀
      (Set.instSDiff.sdiff Set.univ (Finset.instSetLike.coe S))}
  {measure_decomp :
    Eq μ
      (instHAdd.hAdd (GromovCompactness.energyMeasureExtended I u₀)
        (S.sum fun p =>
          instHSMul.hSMul (MeasureTheory.Measure.instFunLike.coe μ (Set.instSingletonSet.singleton p))
            (MeasureTheory.Measure.dirac p)))}
  {σ_1 : GromovCompactness.Bookkeeping.SubseqMap} {μ_1 : MeasureTheory.Measure GromovCompactness.CP1.Elem}
  {μ_fin_1 : MeasureTheory.IsFiniteMeasure μ_1}
  {μ_total_le_1 : ENNReal.instLE.le (MeasureTheory.Measure.instFunLike.coe μ_1 Set.univ) (ENNReal.ofReal B)}
  {weak_lim_1 :
    GromovCompactness.Compactness.WeakMeasureConvergence
      (fun n => GromovCompactness.energyMeasureExtended I (u_seq (σ_1.val n))) μ_1}
  {S_1 : Finset GromovCompactness.CP1.Elem}
  {S_def_1 :
    ∀ (p : GromovCompactness.CP1.Elem),
      Iff (SetLike.instMembership.mem S_1 p)
        (ENNReal.instLE.le (ENNReal.ofReal thresh.ε_reg)
          (MeasureTheory.Measure.instFunLike.coe μ_1 (Set.instSingletonSet.singleton p)))}
  {card_S_mul_le_1 : Real.instLE.le (instHMul.hMul S_1.card.cast thresh.ε_reg) B}
  {card_S_le_1 : Real.instLE.le S_1.card.cast (instHDiv.hDiv B thresh.ε_reg)} {u₀_1 : GromovCompactness.CP1.Elem → M}
  {u₀_jhol_1 : GromovCompactness.JHolomorphicOn I GromovCompactness.I_CP1 u₀_1 Set.univ}
  {smooth_conv_1 :
    GromovCompactness.SmoothLocalConvergesOn I (fun n => u_seq (σ_1.val n)) u₀_1
      (Set.instSDiff.sdiff Set.univ (Finset.instSetLike.coe S_1))}
  {measure_decomp_1 :
    Eq μ_1
      (instHAdd.hAdd (GromovCompactness.energyMeasureExtended I u₀_1)
        (S_1.sum fun p =>
          instHSMul.hSMul (MeasureTheory.Measure.instFunLike.coe μ_1 (Set.instSingletonSet.singleton p))
            (MeasureTheory.Measure.dirac p)))},
  Eq
      { σ := σ, μ := μ, μ_fin := μ_fin, μ_total_le := μ_total_le, weak_lim := weak_lim, S := S, S_def := S_def,
        card_S_mul_le := card_S_mul_le, card_S_le := card_S_le, u₀ := u₀, u₀_jhol := u₀_jhol,
        smooth_conv := smooth_conv, measure_decomp := measure_decomp }
      { σ := σ_1, μ := μ_1, μ_fin := μ_fin_1, μ_total_le := μ_total_le_1, weak_lim := weak_lim_1, S := S_1,
        S_def := S_def_1, card_S_mul_le := card_S_mul_le_1, card_S_le := card_S_le_1, u₀ := u₀_1, u₀_jhol := u₀_jhol_1,
        smooth_conv := smooth_conv_1, measure_decomp := measure_decomp_1 } →
    And (Eq σ σ_1) (And (Eq μ μ_1) (And (Eq S S_1) (Eq u₀ u₀_1)))

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace Real E] {H : Type u_2}
  [inst_2 : TopologicalSpace H] {I : ModelWithCorners Real E H} {M : Type u_3} [inst_3 : MetricSpace M]
  [inst_4 : ChartedSpace H M] [inst_5 : IsManifold I (WithTop.some instTopENat.top) M] [inst_6 : CompactSpace M]
  [inst_7 : GromovCompactness.ClosedTameTarget I M] {thresh : GromovCompactness.Bubbling.TargetThresholds I M}
  {m_defect : Real} {base_val : M} (self : GromovCompactness.Bubbling.LocalDefectTree I thresh m_defect base_val)
  (v : self.tree.V), GromovCompactness.JHolomorphicOn I GromovCompactness.I_CP1 (self.map v) Set.univ

∀ {E : Type u_1} {H : Type u_2} {M : Type u_3} {E' : Type u_4} {H' : Type u_5} {M' : Type u_6}
  [inst : NormedAddCommGroup E] [inst_1 : NormedSpace Real E] [inst_2 : TopologicalSpace H]
  (I : ModelWithCorners Real E H) [inst_3 : TopologicalSpace M] [inst_4 : ChartedSpace H M]
  [inst_5 : NormedAddCommGroup E'] [inst_6 : NormedSpace Real E'] [inst_7 : TopologicalSpace H']
  (I' : ModelWithCorners Real E' H') [inst_8 : TopologicalSpace M'] [inst_9 : ChartedSpace H' M'] {f : M → M'}
  {s : Set M}, (∀ (n : Nat), ContMDiffOn I I' n.cast f s) → ContMDiffOn I I' (WithTop.some instTopENat.top) f s

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace Real E] {H : Type u_2}
  [inst_2 : TopologicalSpace H] {I : ModelWithCorners Real E H} {M : Type u_3} [inst_3 : MetricSpace M]
  [inst_4 : ChartedSpace H M] [inst_5 : IsManifold I (WithTop.some instTopENat.top) M] [inst_6 : CompactSpace M]
  [inst_7 : GromovCompactness.ClosedTameTarget I M] {k : Nat}
  {u_seq : Nat → GromovCompactness.Extensions.MarkedStableMap I k}
  {u_lim : GromovCompactness.Extensions.MarkedStableMap I k}
  (self : GromovCompactness.Extensions.MarkedGromovWitness I u_seq u_lim) (v w : u_lim.tree.V)
  (h : u_lim.tree.adj.Adj v w) (K : Set GromovCompactness.CP1.Elem),
  Set.instLE.le K (GromovCompactness.punctured_sphere (Set.instSingletonSet.singleton (u_lim.tree.node_point w v ⋯))) →
    IsCompact K →
      TendstoUniformlyOn (fun n => EquivLike.toFunLike.coe ((self.frames v n).inv.comp (self.frames w n)).toHomeo)
        (fun x => u_lim.tree.node_point v w h) Filter.atTop K

∀ (T₁ T₂ : GromovCompactness.SphereTree) (v₁ : T₁.V) (v₂ : T₂.V) {x : Sum T₁.V T₂.V}
  (p : (GromovCompactness.graftAdj T₁ T₂ v₁ v₂).Walk x x),
  p.IsCycle → Not (List.instMembership.mem p.edges (Sym2.mk (Sum.inl v₁) (Sum.inr v₂)))

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace Real E] {H : Type u_2}
  [inst_2 : TopologicalSpace H] {I : ModelWithCorners Real E H} {M : Type u_3} [inst_3 : MetricSpace M]
  [inst_4 : ChartedSpace H M] [inst_5 : IsManifold I (WithTop.some instTopENat.top) M] [inst_6 : CompactSpace M]
  [inst_7 : GromovCompactness.ClosedTameTarget I M] {thresh : GromovCompactness.Bubbling.TargetThresholds I M}
  {m_defect : Real} {base_val : M}
  {decomp : GromovCompactness.Bubbling.OneLevelDecomposition I thresh m_defect base_val} {s : Finset Complex}
  (self : GromovCompactness.Bubbling.PartialGraftedTree I thresh m_defect base_val decomp s) (w : self.tree.V)
  (h : self.tree.adj.Adj self.root w),
  Exists fun z =>
    And (SetLike.instMembership.mem s z)
      (Eq (self.tree.node_point self.root w h) (GromovCompactness.stereo_chart.symm.toFun' z))

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace Real E] {H : Type u_2}
  [inst_2 : TopologicalSpace H] {I : ModelWithCorners Real E H} {M : Type u_3} [inst_3 : MetricSpace M]
  [inst_4 : ChartedSpace H M] [inst_5 : IsManifold I (WithTop.some instTopENat.top) M] [inst_6 : CompactSpace M]
  [inst_7 : GromovCompactness.ClosedTameTarget I M] {thresh : GromovCompactness.Bubbling.TargetThresholds I M}
  {m_defect : Real} {base_val : M}
  {decomp : GromovCompactness.Bubbling.OneLevelDecomposition I thresh m_defect base_val} {s : Finset Complex}
  (self : GromovCompactness.Bubbling.PartialGraftedTree I thresh m_defect base_val decomp s),
  Eq (self.map self.root) decomp.v

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace Real E] {H : Type u_2}
  [inst_2 : TopologicalSpace H] {I : ModelWithCorners Real E H} {M : Type u_3} [inst_3 : MetricSpace M]
  [inst_4 : ChartedSpace H M] [inst_5 : IsManifold I (WithTop.some instTopENat.top) M] [inst_6 : CompactSpace M]
  [inst_7 : GromovCompactness.ClosedTameTarget I M] {thresh : GromovCompactness.Bubbling.TargetThresholds I M}
